from pathlib import Path
import re

# Capture the production hub itself; do not maintain a second copy of its layout.
source = Path('lib/screens/home_shell_v3.dart').read_text()
def relocate(match):
    path = match.group(1)
    if path.startswith(('package:', 'dart:')):
        return match.group(0)
    path = '../lib/' + path[3:] if path.startswith('../') else '../lib/screens/' + path
    return "import '" + path + "';"
source = re.sub(r"import '([^']+)';", relocate, source)
prefix = "import 'dart:io';\nimport 'dart:ui' as ui;\n\nimport 'package:flutter/rendering.dart';\nimport 'package:flutter/services.dart';\n\nimport '../lib/theme/app_theme.dart';\n\nimport 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\n\n\n\n"
suffix = "\nvoid main() {\n  TestWidgetsFlutterBinding.ensureInitialized();\n  setUp(() async {\n    final flutterRoot = Platform.environment['FLUTTER_ROOT'];\n    if (flutterRoot != null) {\n      // Explicit component text styles inherit the test font; provide its real glyphs too.\n      final fallback = FontLoader('Ahem');\n      fallback.addFont(\n        File(\n          '$flutterRoot/bin/cache/artifacts/material_fonts/Roboto-Regular.ttf',\n        ).readAsBytes().then(ByteData.sublistView),\n      );\n      await fallback.load();\n      final font = FontLoader('Roboto');\n      for (final name in ['Roboto-Regular.ttf', 'Roboto-Bold.ttf']) {\n        final f = File('$flutterRoot/bin/cache/artifacts/material_fonts/$name');\n        if (await f.exists())\n          font.addFont(\n            Future.value(ByteData.sublistView(await f.readAsBytes())),\n          );\n      }\n      await font.load();\n      final icon = File(\n        '$flutterRoot/bin/cache/artifacts/material_fonts/MaterialIcons-Regular.otf',\n      );\n      if (await icon.exists())\n        await (FontLoader('MaterialIcons')..addFont(\n              Future.value(ByteData.sublistView(await icon.readAsBytes())),\n            ))\n            .load();\n    }\n  });\n  testWidgets(\n    'original route hub fits a narrow phone',\n    (tester) async {\n      tester.view.physicalSize = const Size(390, 844);\n      tester.view.devicePixelRatio = 1;\n      addTearDown(tester.view.resetPhysicalSize);\n      addTearDown(tester.view.resetDevicePixelRatio);\n      final boundary = GlobalKey();\n      await tester.pumpWidget(\n        MaterialApp(\n          debugShowCheckedModeBanner: false,\n          theme: AppTheme.dark.copyWith(\n            textTheme: AppTheme.dark.textTheme.apply(fontFamily: 'Roboto'),\n            appBarTheme: AppTheme.dark.appBarTheme.copyWith(\n              titleTextStyle: AppTheme.dark.appBarTheme.titleTextStyle\n                  ?.copyWith(fontFamily: 'Roboto'),\n            ),\n            filledButtonTheme: FilledButtonThemeData(\n              style: AppTheme.dark.filledButtonTheme.style?.copyWith(\n                textStyle: WidgetStatePropertyAll(\n                  AppTheme.dark.filledButtonTheme.style?.textStyle\n                          ?.resolve({})\n                          ?.copyWith(fontFamily: 'Roboto') ??\n                      const TextStyle(fontFamily: 'Roboto'),\n                ),\n              ),\n            ),\n          ),\n          home: RepaintBoundary(\n            key: boundary,\n            child: Scaffold(body: _PlanningHub(onOpenNearby: () {})),\n          ),\n        ),\n      );\n      await tester.pumpAndSettle();\n      await tester.runAsync(() async {\n        final render =\n            boundary.currentContext!.findRenderObject()!\n                as RenderRepaintBoundary;\n        final image = await render.toImage(pixelRatio: 1);\n        final bytes = await image.toByteData(format: ui.ImageByteFormat.png);\n        await File('/tmp/restored-route-review.png')\n            .writeAsBytes(bytes!.buffer.asUint8List());\n        image.dispose();\n      });\n      expect(find.text('Bugün ne yapalım?'), findsNothing);\n      expect(find.text('Türkiye’yi keşfet'), findsNothing);\n      expect(find.text('Akıllı rota'), findsOneWidget);\n      expect(tester.takeException(), isNull);\n    },\n  );\n\n  testWidgets('city selection enables both manual stop entry methods without catalog data', (tester) async {\n    tester.view.physicalSize = const Size(390, 844);\n    tester.view.devicePixelRatio = 1;\n    addTearDown(tester.view.resetPhysicalSize);\n    addTearDown(tester.view.resetDevicePixelRatio);\n    final boundary = GlobalKey();\n    await tester.pumpWidget(MaterialApp(\n      debugShowCheckedModeBanner: false,\n      theme: AppTheme.dark.copyWith(textTheme: AppTheme.dark.textTheme.apply(fontFamily: 'Roboto')),\n      home: RepaintBoundary(key: boundary, child: const SmartPlanScreen()),\n    ));\n    await tester.pumpAndSettle();\n    await tester.tap(find.byType(TextFormField));\n    await tester.pumpAndSettle();\n    await tester.enterText(find.byWidgetPredicate((w) => w is TextField && w.decoration?.hintText == 'Şehir ara'), 'Elazığ');\n    await tester.pumpAndSettle();\n    await tester.tap(find.widgetWithText(ListTile, 'Elazığ'));\n    await tester.pumpAndSettle();\n    expect(tester.widget<OutlinedButton>(find.widgetWithText(OutlinedButton, 'Noktalardan seç')).onPressed, isNotNull);\n    expect(tester.widget<OutlinedButton>(find.widgetWithText(OutlinedButton, 'Haritadan seç')).onPressed, isNotNull);\n    expect(tester.takeException(), isNull);\n    await tester.runAsync(() async {\n      final render = boundary.currentContext!.findRenderObject()! as RenderRepaintBoundary;\n      final image = await render.toImage(pixelRatio: 1);\n      final bytes = await image.toByteData(format: ui.ImageByteFormat.png);\n      await File('/tmp/smart-route-selection-review.png').writeAsBytes(bytes!.buffer.asUint8List());\n      image.dispose();\n    });\n  });\n}\n"
Path('test/restored_route_review_test.dart').write_text(prefix + source + suffix)

